input.sparql:
SELECT ?point ?tsid ?class WHERE {
  ?z a brick:Zone ; rdfs:label "Perimeter_bot_ZN_2" .
  ?point ref:hasTimeseriesId ?tsid ; brick:isPointOf ?z .
  OPTIONAL { ?point rdf:type ?class . }
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  FILTER (CONTAINS(lcase(?label), "ZN_2"))
}

SELECT ?z ?label ?type WHERE {
  ?z rdfs:label ?label .
  OPTIONAL { ?z rdf:type ?type . }
  FILTER (CONTAINS(?label, "Perimeter"))
}

SELECT ?point ?tsid ?class ?label WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_2" .
  ?point brick:isPointOf ?z ;
         ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point rdfs:label ?label }
  OPTIONAL { ?point a ?class }
}

SELECT ?point ?tsid ?class ?label WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_2" .
  ?point brick:isPointOf ?z .
  OPTIONAL { ?point rdfs:label ?label }
  OPTIONAL { ?point a ?class }
}
